"""Transparent rules based on observed endpoint configuration, not imagined CVEs."""
from .config import HTTP_PORTS, HTTPS_PORTS

OWASP = "https://cheatsheetseries.owasp.org/cheatsheets/HTTP_Headers_Cheat_Sheet.html"
MOZILLA_TLS = "https://wiki.mozilla.org/Security/Server_Side_TLS"
SEVERITIES = ("Critical", "High", "Medium", "Low", "Informational")
RUBRIC = {
    "Critical": "Directly verified condition with immediate severe compromise implications (not generated by current rules).",
    "High": "Verified high-impact security defect with clear technical evidence (e.g., authenticated expired certificate).",
    "Medium": "Observed security-control weakness or untrusted endpoint; context and manual validation required.",
    "Low": "Defense-in-depth or limited information-disclosure concern.",
    "Informational": "Observation or possible exposure with no demonstrated exploitability.",
}


def finding(fid: str, title: str, severity: str, target: str, port: int,
            evidence: str, impact: str, remediation: str, reference: str,
            limitations: str) -> dict:
    return {"id": fid, "title": title, "severity": severity, "target": target,
            "port": port, "description": title, "evidence": evidence,
            "impact": impact, "remediation": remediation, "reference": reference,
            "limitations": limitations}


def analyze_http(target: str, http_result: dict) -> list[dict]:
    if http_result.get("error") or http_result.get("status") is None:
        return []
    port, headers, scheme = http_result["port"], http_result["headers"], http_result["scheme"]
    output = []
    is_html = "text/html" in headers.get("content-type", "").lower()
    rules = []
    # A redirect does not render the content whose MIME would be sniffed.
    if not (300 <= http_result["status"] < 400):
        rules.append(("XCTO", "Missing X-Content-Type-Options", "x-content-type-options", "Low",
         "Browsers may MIME-sniff ambiguous content.", "Set X-Content-Type-Options: nosniff."))
    if is_html:
        rules += [
            ("CSP", "Missing Content-Security-Policy", "content-security-policy", "Medium",
             "Absent CSP may reduce mitigation against injected active content.", "Deploy a tested, restrictive Content-Security-Policy."),
        ]
        csp = headers.get("content-security-policy", "").lower()
        if "frame-ancestors" not in csp and headers.get("x-frame-options", "").upper() not in ("DENY", "SAMEORIGIN"):
            output.append(finding("HTTP-FRAME", "No observed clickjacking framing restriction", "Low", target, port,
                "Neither CSP frame-ancestors nor valid X-Frame-Options present in HTML response.",
                "The page could permit undesired framing.",
                "Set CSP frame-ancestors or X-Frame-Options after checking intended embeds.", OWASP,
                "Only sampled the root HEAD response; exploitability depends on page behavior."))
    if scheme == "https":
        rules.append(("HSTS", "Missing Strict-Transport-Security", "strict-transport-security", "Medium",
            "Browsers may lack an HTTPS-only policy for subsequent visits.", "Add a suitable HSTS policy after validating HTTPS readiness."))
    for suffix, title, header, severity, impact, remediation in rules:
        if header not in headers:
            output.append(finding("HTTP-" + suffix, title, severity, target, port,
                f"{scheme.upper()} HEAD / returned {http_result['status']}; {header} header absent.",
                impact, remediation, OWASP,
                "Missing header alone does not establish exploitation; review actual endpoint and browser context."))
    if headers.get("server"):
        output.append(finding("HTTP-BANNER", "Server header disclosed", "Informational", target, port,
            f"Server: {headers['server'][:100]}", "Discloses a server identifier that may assist reconnaissance.",
            "Review whether a detailed Server header is necessary; patching matters more than hiding it.", OWASP,
            "Server banner may be inaccurate; no version-specific vulnerability has been verified."))
    if http_result.get("redirect"):
        output.append(finding("HTTP-REDIRECT", "Redirect observed (not followed)", "Informational", target, port,
            f"Location: {http_result['redirect'][:150]}", "A redirect destination may require a separate authorization check.",
            "Verify redirect destinations and secure transport manually.", OWASP,
            "Redirect was intentionally not followed; destination not scanned."))
    return output


def analyze_tls(target: str, tls: dict) -> list[dict]:
    port = tls["port"]
    results = []
    cert = tls.get("certificate")
    if tls.get("verification_error"):
        results.append(finding("TLS-TRUST", "TLS certificate trust or identity validation failed", "Medium", target, port,
            tls["verification_error"], "Clients cannot establish authenticated server identity.",
            "Install a valid certificate chain whose SAN matches the assessed address; lab self-signed certificates are expected exceptions.",
            MOZILLA_TLS, "Verification can also fail due to missing local CA trust or lab-issued certificates."))
    if cert:
        # A presented DER certificate can be dated even when its identity is
        # untrusted. Never describe that unauthenticated observation as proof
        # of the server's identity or as an independently verified CVE.
        authenticated = tls.get("certificate_authenticated", False)
        if cert["expired"]:
            results.append(finding("TLS-EXPIRED", "Presented TLS certificate is expired",
                "High" if authenticated else "Medium", target, port,
                f"Presented certificate not-after: {cert['not_after']}; identity authenticated: {authenticated}",
                "Clients can reject an expired certificate.",
                "Renew the certificate and establish a valid trust chain.", MOZILLA_TLS,
                "Certificate data were parsed locally; certificate identity was not trusted when verification failed."))
        if cert["not_yet_valid"]:
            results.append(finding("TLS-FUTURE", "Presented TLS certificate is not yet valid",
                "High" if authenticated else "Medium", target, port,
                f"Presented certificate not-before: {cert['not_before']}; identity authenticated: {authenticated}",
                "Clients can reject a certificate before its validity period.",
                "Deploy a currently valid certificate and verify host clocks.", MOZILLA_TLS,
                "Certificate data were parsed locally; identity was not trusted when verification failed."))
    if tls.get("protocol") in ("TLSv1", "TLSv1.1", "SSLv3", "SSLv2"):
        results.append(finding("TLS-OLD", "Outdated negotiated TLS version", "High", target, port,
            f"Negotiated: {tls['protocol']}", "Obsolete protocols can weaken transport protection.",
            "Disable obsolete protocols and prefer TLS 1.2 or TLS 1.3.", MOZILLA_TLS,
            "Only one negotiated version observed; not a complete protocol-support inventory."))
    return results


def analyze_exposure(target: str, ports: list[dict]) -> list[dict]:
    out = []
    for p in ports:
        if p["state"] != "open":
            continue
        port = p["port"]
        if port in (21, 23, 3389, 445, 5900, 6379):
            out.append(finding(f"EXPOSURE-{port}", "Potentially sensitive network service reachable", "Informational", target, port,
                f"TCP connect succeeded on port {port}.", "A reachable service may increase attack surface.",
                "Verify service identity, access controls, business need and network exposure.",
                "https://www.cisa.gov/resources-tools/resources/cross-sector-cybersecurity-performance-goals",
                "Port association is only a hint; reachability does not demonstrate a vulnerability."))
    return out


def analyze(target: str, ports: list[dict], http_results: list[dict], tls_results: list[dict]) -> list[dict]:
    output = analyze_exposure(target, ports)
    for response in http_results:
        output.extend(analyze_http(target, response))
    for result in tls_results:
        output.extend(analyze_tls(target, result))
    order = {s: i for i, s in enumerate(SEVERITIES)}
    return sorted(output, key=lambda item: (order[item["severity"]], item["port"], item["id"]))
